#include <stdio.h>
#include <string.h>
#include <ctype.h>

int main() {
    char s[100005];
    if (fgets(s, sizeof(s), stdin) == NULL) {
        printf("0\n");
        return 0;
    }
    int count = 0;
    for (int i = 0; s[i]; i++) {
        char c = tolower(s[i]);
        if (c == 'a' || c == 'e' || c == 'i' || c == 'o' || c == 'u') {
            count++;
        }
    }
    printf("%d\n", count);
    return 0;
}
